insert into public.faq (category, question, answer, position, published) values ('Boeken en betalen', 'Kan ik via VrijStaan reserveren?', 'Nee. VrijStaan is een gids en neemt geen boekingen aan. Bij elke plek staat of je kunt reserveren. Daar vind je ook de website of het telefoonnummer van de eigenaar.', 10, true);
insert into public.faq (category, question, answer, position, published) values ('Boeken en betalen', 'Kloppen de prijzen?', 'We nemen de prijs over van de website van de plek. Staan daar losse toeslagen, zoals toeristenbelasting, stroom, een extra persoon of een hond, dan zetten we die er apart onder, met het bedrag en waarvoor het geldt. Zijn er meer tarieven, dan tonen we de laagste als "vanaf" en noemen we ook de hoogste. Bovenaan de pagina van de plek zie je wanneer we de gegevens voor het laatst hebben bijgewerkt. Prijzen kunnen per seizoen veranderen. Twijfel je, kijk dan even op de website van de plek.', 20, true);
insert into public.faq (category, question, answer, position, published) values ('Boeken en betalen', 'Wat betekent "toeristenbelasting inbegrepen"?', 'Veel gemeenten vragen toeristenbelasting per persoon per nacht. Bij de ene plek zit die al in de prijs, bij de andere betaal je hem erbij. Weten we het, dan staat het bij de prijs.', 30, true);
insert into public.faq (category, question, answer, position, published) values ('Eigenaren', 'Ik ben eigenaar van een camperplaats. Hoe pas ik mijn gegevens aan?', 'Ga naar de pagina van je plek, tik op "Klopt er iets niet?" en vink aan dat je de eigenaar bent. Je kunt ook naar "Plek aanmelden" gaan en "Ik ben eigenaar" kiezen. We controleren je wijziging en verwerken hem meestal binnen twee werkdagen.', 10, true);
insert into public.faq (category, question, answer, position, published) values ('Eigenaren', 'Hoe claim, verbeter of verwijder ik mijn plek?', 'Kies bij "Plek aanmelden" voor "Ik ben eigenaar", of tik op "Klopt er iets niet?" op de pagina van je plek. Vul je naam en e-mailadres in. Dan kunnen we nagaan of je echt de eigenaar bent. Je kunt gegevens laten aanpassen, toestemming geven voor je eigen foto''s of de plek laten verwijderen. Reviews van bezoekers kun je niet laten weghalen. Vind je dat een review illegale inhoud bevat of de regels breekt, meld hem dan via "Meld inhoud".', 15, true);
insert into public.faq (category, question, answer, position, published) values ('Eigenaren', 'Kost een vermelding iets?', 'Nee. Een vermelding op VrijStaan is gratis.', 20, true);
insert into public.faq (category, question, answer, position, published) values ('Onderweg', 'Hoe werkt "Dichtbij"?', 'Deel je je locatie, dan zie je de plekken om je heen, met de kortste rijtijd bovenaan. Je telefoon rondt je locatie eerst af op ongeveer 1 kilometer. Onze server stuurt dat afgeronde punt naar een routeplanner: OpenRouteService of FOSSGIS, allebei in Duitsland. Je locatie komt niet in onze database.', 10, true);
insert into public.faq (category, question, answer, position, published) values ('Onderweg', 'Hoe berekenen jullie afstanden en rijtijden?', 'We rekenen de route over de weg uit met OpenRouteService of de open routeplanner OSRM. Die werken met de kaart van OpenStreetMap. Zie de rijtijd als een richtgetal. Met verkeer of wegwerkzaamheden kan het anders uitpakken.', 20, true);
insert into public.faq (category, question, answer, position, published) values ('Onderweg', 'Werkt VrijStaan zonder internet?', 'Voor een deel. Zet VrijStaan als app op je beginscherm. Pagina''s die je al hebt bekeken en je bewaarde reis kun je dan ook openen als je even geen bereik hebt.', 30, true);
insert into public.faq (category, question, answer, position, published) values ('Onderweg', 'Hoe zet ik VrijStaan op mijn beginscherm?', 'Op een iPhone: open de site in Safari, tik op het deelknopje en kies "Zet op beginscherm". Op Android: open het menu in Chrome en kies "App installeren" of "Toevoegen aan startscherm".', 40, true);
insert into public.faq (category, question, answer, position, published) values ('Over VrijStaan', 'Wat is VrijStaan?', 'Een onafhankelijke gids voor camperplaatsen in Nederland. Je vindt hier plekken om met de camper te overnachten, met de vertrektijd, prijzen, voorzieningen, foto''s en reviews van andere camperaars. We gokken nooit. Wat we niet weten, staat er als onbekend.', 10, true);
insert into public.faq (category, question, answer, position, published) values ('Over VrijStaan', 'Wat betekenen "Zonder vertrektijd", "Uitslapers" en "Overige plekken"?', 'De plekken staan in drie groepen. Bij "Zonder vertrektijd" zegt de website van de plek dat je vertrekt wanneer je wilt, of je betaalt per 24 uur vanaf je aankomst. Bij "Uitslapers" is de vaste vertrektijd 12:00 of later. Onder "Overige plekken" vertrek je om 11:00 of 11:30, eerder dan 11:00, of weten we de vertrektijd nog niet. Tijden voor chalets, verhuur of de receptie tellen niet mee. Staat er iets tegenstrijdigs op de website, dan laten we het leeg. Regels kunnen veranderen, bijvoorbeeld in het hoogseizoen. Twijfel je, vraag het dan even na bij de plek.', 15, true);
insert into public.faq (category, question, answer, position, published) values ('Over VrijStaan', 'Kost VrijStaan iets?', 'Nee. Zoeken, plekken bewaren en je reis plannen kost niets. Je betaalt alleen de camperplaats zelf, rechtstreeks aan de eigenaar.', 20, true);
insert into public.faq (category, question, answer, position, published) values ('Over VrijStaan', 'Waar komen de gegevens vandaan?', 'De basis komt uit OpenStreetMap, een open kaart die vrijwilligers bijhouden. We vullen die aan met wat op de website van de plek staat, zoals prijzen, toeslagen, voorzieningen en vertrektijden. Meldingen van camperaars en eigenaren verwerken we ook, nadat we ze hebben gecontroleerd. Wat we niet weten, laten we leeg.', 30, true);
insert into public.faq (category, question, answer, position, published) values ('Over VrijStaan', 'Waarom staat mijn favoriete plek er niet tussen?', 'Een plek komt pas online als we de belangrijkste dingen weten. Er moet een website of telefoonnummer zijn. Van de vertrektijd, de openingsperiode, stroom en de prijs moeten we er minstens twee kennen. En in totaal moeten we ruim de helft weten van wat camperaars willen weten. De vertrektijd en de openingsperiode tellen daarbij het zwaarst. Mis je een plek, meld hem dan aan via "Plek aanmelden". Wij vullen de gegevens aan.', 40, true);
insert into public.faq (category, question, answer, position, published) values ('Over VrijStaan', 'Waarom staat er bij sommige plekken geen foto?', 'We tonen foto''s van Wikimedia Commons, uit onze eigen opslag en van de website van de plek. Op foto''s van Wikimedia en van websites staat klein waar ze vandaan komen. Is er geen foto, dan zie je een tekening. Ben je eigenaar of maker van een foto en wil je dat hij verdwijnt, meld het dan via "Meld inhoud" onderaan de pagina. Dan halen we hem weg.', 45, true);
insert into public.faq (category, question, answer, position, published) values ('Over VrijStaan', 'Hoe werkt de volgorde "Aanbevolen"?', 'Elke plek krijgt punten. Tot 2 punten voor hoe volledig de gegevens zijn. Tot 1 punt voor het gemiddelde reviewcijfer, helemaal vanaf 5 reviews. 0,3 punt voor een foto. 0,3 punt als er geen vertrektijd is, of 0,15 punt als je tot 12:00 of later mag blijven. Kies je een bestemming, dan gaan er punten af naarmate een plek verder weg ligt. Plekken die volgens hun seizoen nu dicht zijn, staan altijd onderaan. Niemand kan betalen voor een hogere plek. Je kunt ook sorteren op afstand, laagste prijs of beste score. Meer uitleg staat op de pagina "Reviews en ranking".', 50, true);
insert into public.faq (category, question, answer, position, published) values ('Over VrijStaan', 'Hoe meld ik foute of illegale inhoud?', 'Klopt een prijs, voorziening of openingstijd niet, tik dan op "Klopt er iets niet?" op de pagina van de plek. Gaat het om een review, foto of tekst die volgens jou illegaal is, je rechten schendt of niet klopt, gebruik dan "Meld inhoud" onderaan elke pagina. Je krijgt een eigen link waar je ziet hoe het ervoor staat. We reageren zo snel mogelijk, uiterlijk binnen 5 werkdagen. Je hoort wat we besluiten en waarom.', 60, true);
insert into public.faq (category, question, answer, position, published) values ('Over VrijStaan', 'Wat betekenen de icoontjes bij een plek?', 'Een bosgroen vierkantje betekent dat de voorziening er is. Een zandkleurig vierkantje betekent dat we het niet weten. Is het icoontje doorgestreept, dan is de voorziening er niet. De klok laat de vertrektijd zien. Tik op "Wat betekenen de icoontjes?" voor de uitleg bij alle icoontjes.', 70, true);
insert into public.faq (category, question, answer, position, published) values ('Privacy', 'Welke gegevens bewaren jullie?', 'Zo weinig mogelijk. Je bewaarde reis staat alleen op je eigen apparaat. Stuur je een bericht of review, dan bewaren we je naam en e-mailadres, zodat we kunnen reageren. Alles staat in de privacyverklaring.', 10, true);
insert into public.faq (category, question, answer, position, published) values ('Privacy', 'Gebruiken jullie cookies?', 'Nee, we plaatsen geen cookies bij bezoekers. Je reis, je instellingen en je cookiekeuze staan wel in de lokale opslag van je browser. Kies je "Statistieken toestaan", dan tellen we welke pagina''s, zoekopdrachten en plekken worden bekeken. Dat komt in onze eigen database, zonder IP-adres, en we bewaren het 13 maanden. Meer staat in het cookiebeleid.', 20, true);
insert into public.faq (category, question, answer, position, published) values ('Privacy', 'Hoe wijzig ik mijn keuze voor statistieken?', 'Tik op "Cookie-instellingen" onderaan elke pagina. Wijzigen gaat net zo makkelijk als kiezen. We leggen je keuze vast als bewijs, met een willekeurig id, de versie van de melding en het tijdstip.', 25, true);
insert into public.faq (category, question, answer, position, published) values ('Privacy', 'Wat doen jullie met mijn locatie?', 'We gebruiken je locatie alleen als je daar zelf om vraagt en je browser het toestaat. Je telefoon rondt je locatie eerst af op ongeveer 1 kilometer. Je precieze locatie verlaat je apparaat dus niet. Onze server stuurt het afgeronde punt en je bestemming naar een routeplanner om de rijtijd uit te rekenen: OpenRouteService (HeiGIT gGmbH, Heidelberg) of routing.openstreetmap.de (FOSSGIS e.V., Duitsland). We gebruiken het alleen daarvoor en zetten het niet in onze database. De knop "Open in navigatie" opent Google Maps. Daar gelden de regels van Google.', 30, true);
insert into public.faq (category, question, answer, position, published) values ('Reviews', 'Wie mag een review schrijven?', 'Iedereen die op de plek heeft gestaan. Je hebt geen account nodig. Schrijf over je eigen ervaring, zonder persoonsgegevens van anderen, reclame of beledigingen. Ben je eigenaar of werk je voor een plek, schrijf dan geen review over die plek of over een concurrent.', 10, true);
insert into public.faq (category, question, answer, position, published) values ('Reviews', 'Hoe controleren jullie reviews?', 'Iemand van ons leest elke review voordat hij online komt, meestal binnen twee werkdagen. We kijken of hij over de plek gaat. Reviews met persoonsgegevens van anderen, beledigingen, haat of reclame plaatsen we niet. We veranderen niets aan de tekst, en een negatieve review plaatsen we net zo goed als een positieve. We controleren niet of je echt op de plek bent geweest en ook niet wie je bent. We nemen geen boekingen aan en sturen geen bevestigingsmail. Reviews zijn dus niet geverifieerd. Eigenaren kunnen reviews niet laten verwijderen.', 15, true);
insert into public.faq (category, question, answer, position, published) values ('Reviews', 'Hoe komt de score tot stand?', 'De score is het gemiddelde van alle goedgekeurde reviews, op een schaal van 1 tot 10. Camperaars geven daarnaast aparte cijfers voor ligging, rust, voorzieningen en prijs/kwaliteit.', 20, true);
